-- Cache existing raw and neighbor values once per visit mutation instead of
-- repeatedly expanding the logical raw view during SQLite trigger preparation.
-- All added fields are transaction-local scratch, cleared by the existing queue
-- triggers. No retained occurrence, collected identifier, or metric changes.
-- Generated by src/vane/analytics/visits/generate-work-cache.py.

ALTER TABLE vane_visit_work ADD COLUMN site INTEGER;

ALTER TABLE vane_visit_work ADD COLUMN context INTEGER;

ALTER TABLE vane_visit_work ADD COLUMN day TEXT;

ALTER TABLE vane_visit_work ADD COLUMN visitor INTEGER;

ALTER TABLE vane_visit_work ADD COLUMN site_id TEXT;

ALTER TABLE vane_visit_work ADD COLUMN at INTEGER;

ALTER TABLE vane_visit_work ADD COLUMN at_offset INTEGER;

ALTER TABLE vane_visit_work ADD COLUMN token BLOB;

ALTER TABLE vane_visit_work ADD COLUMN identity TEXT;

ALTER TABLE vane_visit_work ADD COLUMN prev_at INTEGER;

ALTER TABLE vane_visit_work ADD COLUMN prev_context INTEGER;

ALTER TABLE vane_visit_work ADD COLUMN prev_engaged INTEGER;

ALTER TABLE vane_visit_work ADD COLUMN prev_scroll INTEGER;

ALTER TABLE vane_visit_work ADD COLUMN prev_visit INTEGER;

ALTER TABLE vane_visit_work ADD COLUMN next_at INTEGER;

ALTER TABLE vane_visit_work ADD COLUMN next_visit INTEGER;

DROP TRIGGER vane_visit_append;

DROP TRIGGER vane_visit_detail_change;

DROP VIEW vane_visit_work_values;

CREATE TRIGGER vane_visit_append AFTER INSERT ON vane_visit_work WHEN NEW.action='insert' BEGIN
 UPDATE vane_visit_work SET
 (site,context,day,visitor,site_id,at,at_offset,token,identity)=(
 SELECT e.site,e.context,c.day,c.visitor,s.site_id,e.at_offset+unixepoch(c.day)*1000,e.at_offset,e.token,
  CASE  WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||( CASE  WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value  END )
 ELSE s.site_id||' d '||c.day||' '||( CASE  WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value  END )  END 
 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context
 JOIN vane_raw_sites s ON s.site=e.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor
 LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE e.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET prev=(SELECT (SELECT candidate.raw_id FROM vane_raw_contexts cx JOIN vane_raw_events candidate ON candidate.raw_id=(
 SELECT x.raw_id FROM vane_raw_events x WHERE x.context=cx.context AND (x.at_offset,x.token)<(r.at_offset,r.token)
 ORDER BY x.at_offset DESC,x.token DESC LIMIT 1)
 WHERE cx.site=r.site AND cx.day=r.day AND cx.visitor=r.visitor AND cx.kind='pageview'
 ORDER BY candidate.at_offset DESC,candidate.token DESC LIMIT 1) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id),next=(SELECT (SELECT candidate.raw_id FROM vane_raw_contexts cx JOIN vane_raw_events candidate ON candidate.raw_id=(
 SELECT x.raw_id FROM vane_raw_events x WHERE x.context=cx.context AND (x.at_offset,x.token)>(r.at_offset,r.token)
 ORDER BY x.at_offset ASC,x.token ASC LIMIT 1)
 WHERE cx.site=r.site AND cx.day=r.day AND cx.visitor=r.visitor AND cx.kind='pageview'
 ORDER BY candidate.at_offset ASC,candidate.token ASC LIMIT 1) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id),gap=(SELECT (COALESCE((SELECT json_extract(d.value,'$.minutes') FROM vane_sites s,json_each(s.config_json,'$.definitions') d WHERE s.id=r.site_id AND json_extract(d.value,'$.metric')='visit-timeout' AND json_extract(d.value,'$.from')<=r.day ORDER BY json_extract(d.value,'$.from') DESC,CAST(d.key AS INTEGER) DESC LIMIT 1),30)*60000) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET
 (prev_at,prev_context,prev_engaged,prev_scroll,prev_visit,next_at,next_visit)=(
 SELECT p.at_offset+unixepoch(pc.day)*1000,p.context,pd.engaged_at,pd.scroll,p.visit_id,
 n.at_offset+unixepoch(nc.day)*1000,n.visit_id
 FROM vane_visit_work w
 LEFT JOIN vane_raw_events p ON p.raw_id=w.prev
 LEFT JOIN vane_raw_contexts pc ON pc.context=p.context
 LEFT JOIN vane_raw_details pd ON pd.raw_id=p.raw_id
 LEFT JOIN vane_raw_events n ON n.raw_id=w.next
 LEFT JOIN vane_raw_contexts nc ON nc.context=n.context
 WHERE w.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET left_visit=  CASE   WHEN (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT prev_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)   END  ,right_visit=  CASE   WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)   END  ,
 old_on_page=  CASE   WHEN (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT prev_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)   END   WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_page_frequencies SET n=n-1 WHERE visit=(SELECT prev_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND context=(SELECT prev_context FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND on_page=(SELECT old_on_page FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND scroll=COALESCE((SELECT prev_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1) AND (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL;
 DELETE FROM vane_visit_page_frequencies WHERE visit=(SELECT prev_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND n=0;
 INSERT INTO vane_visit_page_frequencies(visit,context,on_page,scroll,n)
 SELECT (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id),context,on_page,scroll,n FROM vane_visit_page_frequencies WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)!=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)
 ON CONFLICT(visit,context,on_page,scroll) DO UPDATE SET n=n+excluded.n;
 UPDATE vane_visit_facts SET pages=pages+(SELECT pages FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)),
 engaged=engaged+(SELECT engaged FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)),
 last_at=(SELECT last_at FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)),last_raw=(SELECT last_raw FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)),
 last_signal=MAX(last_signal,(SELECT last_signal FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id))),identity=MAX(identity,(SELECT identity FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)))
 WHERE visit=(SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)!=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
 UPDATE vane_raw_events SET visit_id=(SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) WHERE visit_id=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)!=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
 DELETE FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)!=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
 INSERT INTO vane_visit_facts(site,day,visitor,first_raw,last_raw,started,last_at,last_signal,pages,engaged,identity,first_on_page)
 SELECT site,day,visitor,raw_id,raw_id,at,at,at,0,0,identity,0 FROM vane_visit_work WHERE raw_id=NEW.raw_id AND left_visit IS NULL AND right_visit IS NULL;
 UPDATE vane_visit_work SET visit=COALESCE(left_visit,right_visit,last_insert_rowid()) WHERE raw_id=NEW.raw_id;
 UPDATE vane_raw_events SET visit_id=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 INSERT INTO vane_visit_page_frequencies(visit,context,on_page,scroll,n) SELECT (SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT context FROM vane_visit_work WHERE raw_id=NEW.raw_id),  CASE   WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)   END  ,COALESCE((SELECT new_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1),1 WHERE 1
 ON CONFLICT(visit,context,on_page,scroll) DO UPDATE SET n=n+1;
 INSERT INTO vane_visit_page_frequencies(visit,context,on_page,scroll,n) SELECT (SELECT prev_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT prev_context FROM vane_visit_work WHERE raw_id=NEW.raw_id),  CASE   WHEN (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE (SELECT old_on_page FROM vane_visit_work WHERE raw_id=NEW.raw_id)   END  ,COALESCE((SELECT prev_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1),1 WHERE (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL
 ON CONFLICT(visit,context,on_page,scroll) DO UPDATE SET n=n+1;
 UPDATE vane_visit_facts SET pages=pages+1,engaged=engaged+((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL),
 first_on_page=  CASE   WHEN ((SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT token FROM vane_visit_work WHERE raw_id=NEW.raw_id))<(started,(SELECT token FROM vane_raw_events WHERE raw_id=first_raw)) OR pages=0 THEN   CASE   WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)   END  
 WHEN first_raw=(SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE first_on_page   END  ,
 first_raw=  CASE   WHEN ((SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT token FROM vane_visit_work WHERE raw_id=NEW.raw_id))<(started,(SELECT token FROM vane_raw_events WHERE raw_id=first_raw)) THEN NEW.raw_id ELSE first_raw   END  ,
 last_raw=  CASE   WHEN ((SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT token FROM vane_visit_work WHERE raw_id=NEW.raw_id))>(last_at,(SELECT token FROM vane_raw_events WHERE raw_id=last_raw)) THEN NEW.raw_id ELSE last_raw   END  ,
 started=MIN(started,(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)),last_at=MAX(last_at,(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)),last_signal=MAX(last_signal,(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id))),identity=MAX(identity,(SELECT identity FROM vane_visit_work WHERE raw_id=NEW.raw_id))
 WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
 DELETE FROM vane_visit_work WHERE raw_id=NEW.raw_id;
  END  ;

CREATE TRIGGER vane_visit_detail_change AFTER INSERT ON vane_visit_work WHEN NEW.action='detail' BEGIN
 UPDATE vane_visit_work SET
 (site,context,day,visitor,site_id,at,at_offset,token,identity)=(
 SELECT e.site,e.context,c.day,c.visitor,s.site_id,e.at_offset+unixepoch(c.day)*1000,e.at_offset,e.token,
  CASE  WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||( CASE  WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value  END )
 ELSE s.site_id||' d '||c.day||' '||( CASE  WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value  END )  END 
 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context
 JOIN vane_raw_sites s ON s.site=e.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor
 LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE e.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET next=(SELECT (SELECT candidate.raw_id FROM vane_raw_contexts cx JOIN vane_raw_events candidate ON candidate.raw_id=(
 SELECT x.raw_id FROM vane_raw_events x WHERE x.context=cx.context AND (x.at_offset,x.token)>(r.at_offset,r.token)
 ORDER BY x.at_offset ASC,x.token ASC LIMIT 1)
 WHERE cx.site=r.site AND cx.day=r.day AND cx.visitor=r.visitor AND cx.kind='pageview'
 ORDER BY candidate.at_offset ASC,candidate.token ASC LIMIT 1) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id),gap=(SELECT (COALESCE((SELECT json_extract(d.value,'$.minutes') FROM vane_sites s,json_each(s.config_json,'$.definitions') d WHERE s.id=r.site_id AND json_extract(d.value,'$.metric')='visit-timeout' AND json_extract(d.value,'$.from')<=r.day ORDER BY json_extract(d.value,'$.from') DESC,CAST(d.key AS INTEGER) DESC LIMIT 1),30)*60000) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id),visit=(SELECT visit_id FROM vane_raw_events WHERE raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET
 (prev_at,prev_context,prev_engaged,prev_scroll,prev_visit,next_at,next_visit)=(
 SELECT p.at_offset+unixepoch(pc.day)*1000,p.context,pd.engaged_at,pd.scroll,p.visit_id,
 n.at_offset+unixepoch(nc.day)*1000,n.visit_id
 FROM vane_visit_work w
 LEFT JOIN vane_raw_events p ON p.raw_id=w.prev
 LEFT JOIN vane_raw_contexts pc ON pc.context=p.context
 LEFT JOIN vane_raw_details pd ON pd.raw_id=p.raw_id
 LEFT JOIN vane_raw_events n ON n.raw_id=w.next
 LEFT JOIN vane_raw_contexts nc ON nc.context=n.context
 WHERE w.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET old_on_page=  CASE   WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE(old_engaged-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)   END   WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_page_frequencies SET n=n-1 WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND context=(SELECT context FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND on_page=(SELECT old_on_page FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND scroll=COALESCE((SELECT old_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1) AND 1;
 DELETE FROM vane_visit_page_frequencies WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND n=0;
 INSERT INTO vane_visit_page_frequencies(visit,context,on_page,scroll,n) SELECT (SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT context FROM vane_visit_work WHERE raw_id=NEW.raw_id),  CASE   WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)   END  ,COALESCE((SELECT new_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1),1 WHERE 1
 ON CONFLICT(visit,context,on_page,scroll) DO UPDATE SET n=n+1;
 UPDATE vane_visit_facts SET engaged=engaged+((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL)-((SELECT old_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL),
 first_on_page=  CASE   WHEN first_raw=NEW.raw_id THEN   CASE   WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)   END   ELSE first_on_page   END  ,
 last_signal=  CASE   WHEN (SELECT old_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)=last_signal AND COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)<(SELECT old_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN
 (SELECT MAX(MAX((r.at_offset+unixepoch(signal_context.day)*1000),COALESCE(  CASE   WHEN r.raw_id=NEW.raw_id THEN (SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE signal_details.engaged_at   END  ,(r.at_offset+unixepoch(signal_context.day)*1000)))) FROM vane_raw_events r JOIN vane_raw_contexts signal_context ON signal_context.context=r.context LEFT JOIN vane_raw_details signal_details ON signal_details.raw_id=r.raw_id WHERE r.visit_id=vane_visit_facts.visit)
 ELSE MAX(last_signal,COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)))   END   WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
 DELETE FROM vane_visit_work WHERE raw_id=NEW.raw_id;
  END  ;
